import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        double n = scanner.nextDouble();
        double minDiffValue = 2e9;
        double ratioValue = x / y;
        long bestNumerator = 0;
        long bestDenominator = 1;
        for (int i = 1; i <= (int) n; i++) {
            long a = (long) (ratioValue * i + 0.4999);
            double currentDiff = Math.abs((double) a / i - ratioValue);
            if (currentDiff < minDiffValue) {
                minDiffValue = currentDiff;
                bestNumerator = a;
                bestDenominator = i;
            }
        }
        System.out.println(bestNumerator + "/" + bestDenominator);
        scanner.close();
    }
}
